#!/usr/bin/env python3
"""Apply CP2P item #10 edits to existing tracked sources."""
from pathlib import Path

ROOT = Path("experiments/media-harness-h1")


def read(rel):
    return (ROOT / rel).read_text()


def write(rel, text):
    (ROOT / rel).write_text(text.rstrip() + "\n")


def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one match, got {count}")
    return text.replace(old, new, 1)


p = Path("mk/media-harness-h1-cp2o-visible-rfb-interaction-pcm.mk")
s = p.read_text()
s = replace_once(s, "H1_MAIN_SOURCE ?= experiments/media-harness-h1/h1_main_rfb_visible_interaction_pcm.c\n\nCALIBRATION_DIR :=", "H1_MAIN_SOURCE ?= experiments/media-harness-h1/h1_main_rfb_visible_interaction_pcm.c\nH1_CONFIG_RFB_GATE_SOURCE ?= experiments/media-harness-h1/h1_config_rfb_pcm_activation_gate.c\n\nCALIBRATION_DIR :=", "CP2O gate variable")
s = replace_once(s, "$(BUILD_DIR)/h1_config_rfb_activation_gate.o: \\\n\texperiments/media-harness-h1/h1_config_rfb_pcm_activation_gate.c \\\n\texperiments/media-harness-h1/h1_config.h \\\n\texperiments/audio-transport/common/transport_protocol.h | $(BUILD_DIR)\n\t$(EE_CC) $(EE_CFLAGS) $(EE_INCS) -c \\\n\t\texperiments/media-harness-h1/h1_config_rfb_pcm_activation_gate.c \\\n\t\t-o $@\n", "$(BUILD_DIR)/h1_config_rfb_activation_gate.o: \\\n\t$(H1_CONFIG_RFB_GATE_SOURCE) \\\n\texperiments/media-harness-h1/h1_config.h \\\n\texperiments/audio-transport/common/transport_protocol.h | $(BUILD_DIR)\n\t$(EE_CC) $(EE_CFLAGS) $(EE_INCS) -c \\\n\t\t$(H1_CONFIG_RFB_GATE_SOURCE) \\\n\t\t-o $@\n", "CP2O gate rule")
p.write_text(s)

p = Path("mk/media-harness-h1-cp2p-application-link.mk")
s = p.read_text()
s = replace_once(s, "# Item #9 links the real exact-generation MPEG worker and generated CP2P\n# decoder/runtime. The public CONFIG gate remains MPEG OFF until item #10, so\n# this checkpoint proves worker readiness without claiming all-guns activation.\n", "# Item #10 opens the CP2P-only visible-RFB + MPEG2 + optional-PCM CONFIG gate.\n# START remains the sole generation/producer activation authority; CONFIG only\n# allocates and authorizes the already-proven transport/decoder capability.\n", "CP2P makefile synopsis")
s = replace_once(s, "H1_MAIN_SOURCE := experiments/media-harness-h1/h1_main_cp2p_visible_interaction_pcm.c\n\ninclude mk/media-harness-h1-cp2o-visible-rfb-interaction-pcm.mk\n", "H1_MAIN_SOURCE := experiments/media-harness-h1/h1_main_cp2p_visible_interaction_pcm.c\nH1_CONFIG_RFB_GATE_SOURCE := experiments/media-harness-h1/h1_config_cp2p_activation_gate.c\n\ninclude mk/media-harness-h1-cp2o-visible-rfb-interaction-pcm.mk\n", "CP2P gate source")
s = replace_once(s, "\t@echo H1_CP2P_MPEG_WORKER=GENERATION_BOUND_GATE_DORMANT\n\t@echo H1_CP2P_MPEG_CANCELLABLE_READ=LIVE\n", "\t@echo H1_CP2P_MPEG_WORKER=GENERATION_BOUND_START_ACTIVATED\n\t@echo H1_CP2P_ITEM10_PUBLIC_MPEG_GATE=LIVE\n\t@echo H1_CP2P_MPEG_CANCELLABLE_READ=LIVE\n", "CP2P proof markers")
p.write_text(s)

s = read("h1_mux_server_cumulative39_rfb_pcm_bridge.py")
s = replace_once(s, 'class H1Cumulative39RfbPcmSession(_ParentSession):\n    """Visible cumulative RFB with optional canonical PCM and no MPEG."""\n\n    def __init__(\n', 'class H1Cumulative39RfbPcmSession(_ParentSession):\n    """Visible cumulative RFB with optional canonical PCM and no MPEG."""\n\n    def _validate_composition_policy(self, profile: dict[str, int]) -> None:\n        if int(profile["rfb_mode"]) != 2:\n            raise base.ProtocolError("CP2O runner requires visible RFB mode 2")\n        if int(profile["video_mode"]) != 0:\n            raise base.ProtocolError("CP2O runner requires MPEG/video OFF")\n        if int(profile["audio_mode"]) not in (0, base.AUDIO_PCM):\n            raise base.ProtocolError("CP2O runner permits only audio OFF or PCM")\n\n    def __init__(\n', "CP2O policy hook")
s = replace_once(s, '        if int(profile["rfb_mode"]) != 2:\n            raise base.ProtocolError("CP2O runner requires visible RFB mode 2")\n        if int(profile["video_mode"]) != 0:\n            raise base.ProtocolError("CP2O runner requires MPEG/video OFF")\n        if int(profile["audio_mode"]) not in (0, base.AUDIO_PCM):\n            raise base.ProtocolError("CP2O runner permits only audio OFF or PCM")\n\n', '        self._validate_composition_policy(profile)\n\n', "CP2O policy dispatch")
write("h1_mux_server_cumulative39_rfb_pcm_bridge.py", s)

s = read("h1_cp2p_mpeg_producer.py")
s = replace_once(s, "The public item-#10 MPEG CONFIG gate deliberately remains closed. Therefore this\nowner does NOT write PSTV frames and does not consume MPEG channel credit. Output\nis archived and held in the existing bounded ProducerBuffer; when its bounded\nunsent queue fills, normal pipe/TCP-style backpressure stalls FFmpeg rather than\ncreating an unbounded queue.\n", "This owner never writes PSTV frames or consumes MPEG credit directly. Item #10's\nsession scheduler may open one exact-generation emission lease after the public\nCP2P CONFIG gate and matching START are both valid. Output remains archived and\nbounded by the existing ProducerBuffer; backpressure still stalls FFmpeg rather\nthan creating an unbounded queue.\n", "producer synopsis")
s = replace_once(s, "        self._emission_in_flight = 0\n", "        self._emission_in_flight = 0\n        self._emission_retiring = False\n", "producer latch init")
s = replace_once(s, "                or self._emission_open\n                or self._emission_in_flight != 0\n", "                or self._emission_open\n                or self._emission_in_flight != 0\n                or self._emission_retiring\n", "producer open latch")
s = replace_once(s, "            self._emission_open = False\n            while self._emission_in_flight != 0:\n", "            self._emission_retiring = True\n            self._emission_open = False\n            while self._emission_in_flight != 0:\n", "producer retire latch")
s = replace_once(s, "        self.generation = generation\n        self.plan = plan\n        self.producer = producer\n        self.archive_path = archive_path\n        if self.attach is not None:\n", "        self.generation = generation\n        self.plan = plan\n        self.producer = producer\n        self.archive_path = archive_path\n        with self._emission_condition:\n            self._emission_open = False\n            self._emission_in_flight = 0\n            self._emission_retiring = False\n        if self.attach is not None:\n", "producer start reset")
s = replace_once(s, '            "state": "live-local-producer-public-mpeg-gate-closed",\n', '            "state": "live-local-producer-awaiting-exact-emission-lease",\n', "producer state")
s = replace_once(s, "        with self._emission_condition:\n            self._emission_open = False\n            self._emission_in_flight = 0\n            self._emission_condition.notify_all()\n        if self.attach is not None:\n", "        with self._emission_condition:\n            self._emission_open = False\n            self._emission_in_flight = 0\n            self._emission_retiring = False\n            self._emission_condition.notify_all()\n        if self.attach is not None:\n", "producer normal reset")
s = replace_once(s, "            with self._emission_condition:\n                self._emission_open = False\n                self._emission_in_flight = 0\n                self._emission_condition.notify_all()\n            if self.attach is not None:\n", "            with self._emission_condition:\n                self._emission_open = False\n                self._emission_in_flight = 0\n                self._emission_retiring = False\n                self._emission_condition.notify_all()\n            if self.attach is not None:\n", "producer forced reset")
write("h1_cp2p_mpeg_producer.py", s)

s = read("h1_cp2p_mpeg_producer_test.py")
s = s.replace('"live-local-producer-public-mpeg-gate-closed"', '"live-local-producer-awaiting-exact-emission-lease"')
s = replace_once(s, "        self.assertIsNone(owner.begin_emission_exact(15))\n\n        owner.finish_emission_exact(15)\n", "        self.assertIsNone(owner.begin_emission_exact(15))\n        with self.assertRaises(base.ProtocolError):\n            owner.open_emission_exact(15)\n\n        owner.finish_emission_exact(15)\n", "producer reopen regression")
write("h1_cp2p_mpeg_producer_test.py", s)

s = read("h1_mux_server_cp2p_start_receiver.py")
s = replace_once(s, "    CP2P Pi runner through item #8: visible RFB + optional PCM, immutable\n    START receive/validation, generation-scoped RFB suppression, exact capture\n    preparation, and one START-driven exact-generation local FFmpeg producer.\n", "    CP2P Pi runner through item #10: visible RFB + optional PCM + START-owned\n    exact-generation MPEG on the existing one-socket PSTV transport.\n", "runner synopsis")
s = replace_once(s, "Item #8 now launches the exact prepared FFmpeg command after suppression and\ncapture preparation succeed. The item-#10 public MPEG gate remains closed, so\nproducer bytes stay local/bounded and no MPEG DATA is emitted onto PSTV yet.\n", "Item #10 opens only the public MPEG CONFIG/scheduler seam. START still launches\nthe exact producer, and the scheduler may emit channel-4 DATA only while it\nholds the matching generation's #11B emission lease. Retirement closes that\nlease before producer stop/drain, so no stale generation can be reopened.\n", "runner item10 text")
s = replace_once(s, "import json\nfrom pathlib import Path\n", "import json\nfrom pathlib import Path\nimport struct\nimport time\n", "runner imports")
s = replace_once(s, "base = cp2o.base\n_ParentSession = cp2o.H1Cumulative39RfbPcmSession\n\n\n", "base = cp2o.base\n_ParentSession = cp2o.H1Cumulative39RfbPcmSession\n\n\ndef _install_cp2p_all_guns_profile() -> None:\n    if \"CP2P_ALL_GUNS\" in base.PROFILES:\n        return\n    profile = dict(base.PROFILES[\"P11_COMPAT_PLUS_PCM\"])\n    profile.update({\n        \"profile_id\": 3,\n        \"rfb_mode\": 2,\n        \"rfb_queue_capacity\": 32768,\n        \"rfb_credit_batch_bytes\": 8192,\n        \"rfb_credit_flush_on_empty\": 1,\n        \"rfb_credit_return_enabled\": 1,\n        \"rfb_initial_credit_bytes\": 32768,\n    })\n    base.PROFILES[\"CP2P_ALL_GUNS\"] = profile\n\n\n_install_cp2p_all_guns_profile()\n\n\n", "runner profile")
s = replace_once(s, '                capture_evidence["state"] = "producer-live-local-gate-closed"\n', '                capture_evidence["state"] = "producer-live-awaiting-exact-emission-lease"\n', "runner evidence")
s = replace_once(s, 'class H1Cp2pStartReceiveSession(_ParentSession):\n    """CP2O baseline plus START, Pi suppression, and exact capture preparation."""\n\n    def __init__(\n', 'class H1Cp2pStartReceiveSession(_ParentSession):\n    """CP2P item #10 all-guns composition on the existing CP2O shell."""\n\n    def _validate_composition_policy(self, profile: dict[str, int]) -> None:\n        if int(profile["rfb_mode"]) != 2:\n            raise base.ProtocolError("CP2P item #10 requires visible RFB mode 2")\n        if int(profile["video_mode"]) != 1:\n            raise base.ProtocolError("CP2P item #10 requires MPEG2 video mode")\n        if int(profile["audio_mode"]) not in (0, base.AUDIO_PCM):\n            raise base.ProtocolError("CP2P item #10 permits only audio OFF or PCM")\n\n    def __init__(\n', "runner policy")
s = replace_once(s, "        self.cp2p_mpeg_producer = H1Cp2pMpegProducer(\n            Path(evidence),\n            attach=lambda producer: setattr(self, \"video_producer\", producer),\n        )\n\n        adapter = self.rfb_session_adapter\n", "        self.cp2p_mpeg_producer = H1Cp2pMpegProducer(\n            Path(evidence),\n            attach=lambda producer: setattr(self, \"video_producer\", producer),\n        )\n        self._cp2p_emission_opened_generations: set[int] = set()\n        self._cp2p_mpeg_generation_order: list[int] = []\n        self._cp2p_mpeg_sent_bytes: dict[int, int] = {}\n        self._cp2p_mpeg_archive_paths: dict[int, Path] = {}\n        self._cp2p_schedule_index = 0\n\n        adapter = self.rfb_session_adapter\n", "runner scheduler state")
methods = (ROOT / ".item10_runner_methods.txt").read_text().rstrip() + "\n\n"
s = replace_once(s, "    def cleanup(self) -> None:\n", methods + "    def cleanup(self) -> None:\n", "runner methods")
write("h1_mux_server_cp2p_start_receiver.py", s)

s = read("h1_main_cp2p_visible_interaction_pcm.c")
s = replace_once(s, " * only application-level composition: it instantiates the CP2P session\n * coordinator so calibration acceptance owns generation prepare/START and the\n * combined RFB policy. Item #9 adds the exact-generation MPEG worker while\n * the public CONFIG gate intentionally keeps live decode dormant until #10.\n", " * only application-level composition: it instantiates the CP2P session\n * coordinator so calibration acceptance owns generation prepare/START and the\n * combined RFB policy. Item #10 now accepts the exact visible-RFB + MPEG2 +\n * optional-PCM CONFIG while START remains the sole decode-generation trigger.\n", "main synopsis")
s = s.replace("mpeg_worker=GENERATION_BOUND_GATE_DORMANT", "mpeg_worker=GENERATION_BOUND_START_ACTIVATED")
s = replace_once(s, "        if (config->rfb_mode != PSTVNC_H1_RFB_ON_VISIBLE ||\n            config->video_mode != PSTVNC_H1_VIDEO_OFF ||\n            (config->audio_mode != PSTVNC_H1_AUDIO_OFF &&\n             config->audio_mode != PSTVNC_H1_AUDIO_PCM)) {\n            printf(\"H1_CP2P=PROFILE_REJECT_NOT_VISIBLE_RFB_OPTIONAL_PCM\\n\");\n            session_ok = 0;\n        }\n", "        if (config->rfb_mode != PSTVNC_H1_RFB_ON_VISIBLE ||\n            config->video_mode != PSTVNC_H1_VIDEO_MPEG2_ES ||\n            (config->audio_mode != PSTVNC_H1_AUDIO_OFF &&\n             config->audio_mode != PSTVNC_H1_AUDIO_PCM)) {\n            printf(\"H1_CP2P=PROFILE_REJECT_NOT_ALL_GUNS\\n\");\n            session_ok = 0;\n        }\n", "main profile")
s = replace_once(s, "            interaction_initialized = 0;\n\n            if (rfb_result_code < 0) {\n", "            interaction_initialized = 0;\n\n            if (config->video_mode == PSTVNC_H1_VIDEO_MPEG2_ES) {\n                printf(\n                    \"H1_CP2P_MPEG_RESULT decoded=%u displayed=%u feed=%u \"\n                    \"payload=%u error=%u\\n\",\n                    (unsigned int)mpeg_worker.result.pictures_decoded,\n                    (unsigned int)mpeg_worker.result.pictures_displayed,\n                    (unsigned int)mpeg_worker.result.feed_calls,\n                    (unsigned int)mpeg_worker.result.payload_bytes_submitted,\n                    (unsigned int)mpeg_worker.result.error);\n                if (mpeg_worker.result.pictures_displayed == 0u) {\n                    printf(\"H1_CP2P=MPEG_PRESENTATION_UNPROVEN\\n\");\n                    session_ok = 0;\n                }\n            }\n\n            if (rfb_result_code < 0) {\n", "main MPEG result")
s = replace_once(s, "        if (!pstvnc_h1_transport_send_result(\n                &transport,\n                0u,\n                0u,\n                0u,\n                0u,\n                0u,\n                0u,\n                0u)) {\n", "        if (!pstvnc_h1_transport_send_result(\n                &transport,\n                mpeg_worker.result.pictures_decoded,\n                mpeg_worker.result.pictures_displayed,\n                mpeg_worker.result.feed_calls,\n                mpeg_worker.result.payload_bytes_submitted,\n                mpeg_worker.result.dma_bytes_submitted,\n                mpeg_worker.result.deadline_misses,\n                (uint32_t)mpeg_worker.result.max_deadline_late_ticks)) {\n", "main send result")
write("h1_main_cp2p_visible_interaction_pcm.c", s)

print("H1_CP2P_ITEM10_EXISTING_PATCH=APPLIED")
